(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const mx = x+w1x, my = y+w1y;
  const w2x = Math.sin(mx*0.03-t*0.4)*8+Math.cos(my*0.025+t*0.3)*6;
  const w2y = Math.cos(my*0.03+t*0.35)*8+Math.sin(mx*0.02-t*0.45)*6;
  const sx = mx+w2x, sy = my+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9],
    [80+Math.sin(t*0.7+3)*60,40+Math.cos(t*0.3)*40,0.11,2.1],
    [400+Math.cos(t*0.6+2)*70,200+Math.sin(t*0.4+1)*50,0.085,1.8],
    [200+Math.sin(t*0.45)*110,220+Math.cos(t*0.65+4)*60,0.095,2.4],
    [300+Math.cos(t*0.55+3)*90,30+Math.sin(t*0.75)*45,0.075,2.2]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.cos(d*f*1.3-t*sp*0.8+0.5); iS2+=Math.sin(d*f*0.5+t*sp*0.4-2.0);
  }
  const act=aS/10,inh=iS/10,act2=aS2/10,inh2=iS2/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.03-t*0.6))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08-t*1.5)*Math.sin(sy*0.06+t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.06-ang*2+t*0.8))*0.3;
  const pulse=Math.sin(dist*0.08-t*2.5)*Math.exp(-dist*0.005)*0.4;
  const reaction=Math.tanh((act-inh*0.7+act2*0.3-inh2*0.2+bg*0.3+spiral+pulse)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.3;
  const micro=Math.sin(sx*0.3+t*1.5)*Math.sin(sy*0.3-t*1.2)*Math.sin((sx+sy)*0.2+t*0.8)*0.15;
  const blend=reaction*0.6+cell*0.25+micro*0.15,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,40,85],[15,85,120],[20,140,130],[45,175,120],[140,190,70],[210,185,55],[225,140,50],[200,85,60],[160,50,70],[100,30,65],[50,15,55],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.75?1.2:Math.abs(reaction)>0.5?1.05:1.0;
  const sh=Math.sin(t*0.2)*0.02;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+sh*30)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+sh*15)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge-sh*20)|0)
  ];
}
